COLOR = {"Confidence": "#2a78d6", "Representation": "#eb6834", "Benign-only": "#1baf7a", "CLAD": "#eda100",
         "XGBoost": "#e87ba4"}
AUC_HI, TPR_LO = 0.75, 0.20          # "looks good by AUC" / "catches few attacks"
OUT = Path.home() / "Downloads"
INK, MUTED, GRID, TRAP = "#2b2b2a", "#6b6b67", "#d9d8d3", "#fbe3dc"

plt.rcParams.update({"font.family": "serif", "font.size": 7, "axes.linewidth": 0.6, "axes.edgecolor": MUTED,
                     "xtick.color": MUTED, "ytick.color": MUTED, "axes.labelcolor": INK, "text.color": INK,
                     "xtick.major.width": 0.5, "ytick.major.width": 0.5, "xtick.major.size": 2, "ytick.major.size": 2})

auc = np.concatenate([np.array(a) for a, _ in POINTS.values()])
tpr = np.concatenate([np.array(t) for _, t in POINTS.values()])
hi = auc >= AUC_HI
n_hi, n_trap, med = int(hi.sum()), int((hi & (tpr < TPR_LO)).sum()), float(np.median(tpr[hi]))

fig, ax = plt.subplots(figsize=(3.45, 2.55))
ax.add_patch(Rectangle((AUC_HI, 0), 1.02 - AUC_HI, TPR_LO, color=TRAP, zorder=0, lw=0))   # the trap zone
ax.annotate(f"AUC trap: {n_trap} of {n_hi} results with\nAUC \u2265 0.75 catch < 20% of attacks", xy=(0.86, 0.13),
            xytext=(0.04, 0.40), fontsize=6, color="#a14a3b", weight="bold", va="center",
            arrowprops=dict(arrowstyle="->", color="#a14a3b", lw=0.7, connectionstyle="arc3,rad=-0.2"))
ax.axvline(AUC_HI, color="#c9a59a", lw=0.6, ls=":", zorder=0)
ax.axhline(TPR_LO, color="#c9a59a", lw=0.6, ls=":", zorder=0)
for f, (a, t) in POINTS.items():
    ax.scatter(a, t, s=5, color=COLOR[f], alpha=0.45, linewidth=0, zorder=2)
for f, (a, t) in POINTS.items():          # family means on top
    ax.scatter(np.mean(a), np.mean(t), s=48, color=COLOR[f], edgecolor=INK, linewidth=0.8, zorder=4)
ax.set_xlim(0.0, 1.02); ax.set_ylim(-0.02, 1.02)
ax.set_xlabel("AUC")
ax.set_ylabel("Attacks caught at 1% FPR")
ax.set_yticks([0, 0.25, 0.5, 0.75, 1.0], ["0%", "25%", "50%", "75%", "100%"])
for s in ("top", "right"):
    ax.spines[s].set_visible(False)
ax.grid(color=GRID, lw=0.4)
ax.set_axisbelow(True)
h = [Line2D([], [], ls="", marker="o", ms=4.5, mfc=COLOR[f], mec=INK, mew=0.6, label=f) for f in COLOR]
ax.legend(handles=h, loc="upper left", frameon=False, fontsize=6, title="family mean", title_fontsize=6,
          handletextpad=0.2, borderaxespad=0.2)
fig.tight_layout(pad=0.2)
fig.savefig(OUT / "fig_operating.pdf", bbox_inches="tight", pad_inches=0.02)
fig.savefig(OUT / "fig_operating.png", dpi=200, bbox_inches="tight", pad_inches=0.02)
print(f"{len(auc)} results; {n_hi} with AUC >= {AUC_HI}; {n_trap} of them catch < 20% (median {med:.2f})")
plt.show()
